"use strict";(self.webpackChunkhn_cho_sh=self.webpackChunkhn_cho_sh||[]).push([[75192],{3331:(e,n,i)=>{i.d(n,{R:()=>a,x:()=>d});var r=i(36672);const t={},s=r.createContext(t);function a(e){const n=r.useContext(s);return r.useMemo((function(){return"function"==typeof e?e(n):{...n,...e}}),[n,e])}function d(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(t):e.components||t:a(e.components),r.createElement(s.Provider,{value:n},e.children)}},89810:(e,n,i)=>{i.r(n),i.d(n,{assets:()=>u,contentTitle:()=>d,default:()=>o,frontMatter:()=>a,metadata:()=>r,toc:()=>l});const r=JSON.parse('{"id":"2023/04/10","title":"2023-04-10","description":"Der LLama-Effekt: Leck l\xf6ste eine Reihe von Open-Source-Alternativen zu ChatGPT aus","source":"@site/i18n/de/docusaurus-plugin-content-docs/current/2023/04/10.md","sourceDirName":"2023/04","slug":"/2023/04/10","permalink":"/de/2023/04/10","draft":false,"unlisted":false,"editUrl":"https://github.com/anaclumos/heimdall/blob/main/i18n/de/docusaurus-plugin-content-docs//current/2023/04/10.md","tags":[],"version":"current","frontMatter":{"localized_date":"10. April 2023","top_news":"Der LLama-Effekt: Leck l\xf6ste eine Reihe von Open-Source-Alternativen zu ChatGPT aus"},"sidebar":"defaultSidebar","previous":{"title":"2023-04-11","permalink":"/de/2023/04/11"},"next":{"title":"2023-04-09","permalink":"/de/2023/04/09"}}');var t=i(23420),s=i(3331);const a={localized_date:"10. April 2023",top_news:"Der LLama-Effekt: Leck l\xf6ste eine Reihe von Open-Source-Alternativen zu ChatGPT aus"},d="2023-04-10",u={},l=[{value:"Der LLama-Effekt: Leck l\xf6ste eine Reihe von Open-Source-Alternativen zu ChatGPT aus",id:"der-llama-effekt-leck-l\xf6ste-eine-reihe-von-open-source-alternativen-zu-chatgpt-aus",level:2},{value:"Von tiefem zu langem Lernen?",id:"von-tiefem-zu-langem-lernen",level:2},{value:"EY wird von neuen Wirtschaftspr\xfcfungsunternehmen in Deutschland ausgeschlossen",id:"ey-wird-von-neuen-wirtschaftspr\xfcfungsunternehmen-in-deutschland-ausgeschlossen",level:2},{value:"Sonnenuntergang am S\xfcdpol",id:"sonnenuntergang-am-s\xfcdpol",level:2},{value:"Niederl\xe4ndischer Journalist, der kritisch \xfcber China schreibt, wird eingesch\xfcchtert",id:"niederl\xe4ndischer-journalist-der-kritisch-\xfcber-china-schreibt-wird-eingesch\xfcchtert",level:2},{value:"Die USPS-Einrichtung in Utah tut nichts anderes, als Handschriften zu entziffern.",id:"die-usps-einrichtung-in-utah-tut-nichts-anderes-als-handschriften-zu-entziffern",level:2},{value:"Apple setzt seine Bem\xfchungen fort, eine gewerkschaftliche Organisierung von Einzelhandelsgesch\xe4ften zu verhindern",id:"apple-setzt-seine-bem\xfchungen-fort-eine-gewerkschaftliche-organisierung-von-einzelhandelsgesch\xe4ften-zu-verhindern",level:2},{value:"PL/Rust 1.0: jetzt eine vertrauensw\xfcrdige Sprache f\xfcr Postgres",id:"plrust-10-jetzt-eine-vertrauensw\xfcrdige-sprache-f\xfcr-postgres",level:2},{value:"Twitter blockiert Likes und Retweets, die Substack erw\xe4hnen",id:"twitter-blockiert-likes-und-retweets-die-substack-erw\xe4hnen",level:2},{value:"Z-Library l\xe4sst Nutzer physische B\xfccher teilen",id:"z-library-l\xe4sst-nutzer-physische-b\xfccher-teilen",level:2},{value:"Perseus - NextJS-Alternative in Rust",id:"perseus---nextjs-alternative-in-rust",level:2},{value:"Ein Baby-GPT",id:"ein-baby-gpt",level:2},{value:"Zwei Arten von Software-Ingenieuren",id:"zwei-arten-von-software-ingenieuren",level:2},{value:"Fortgeschrittene Linux-Programmierung (2001)",id:"fortgeschrittene-linux-programmierung-2001",level:2},{value:"Ein CERN f\xfcr Open-Source-KI im gro\xdfen Ma\xdfstab",id:"ein-cern-f\xfcr-open-source-ki-im-gro\xdfen-ma\xdfstab",level:2},{value:"Permafrost-Engine - Eine in C geschriebene OpenGL-RTS-Spiel-Engine",id:"permafrost-engine---eine-in-c-geschriebene-opengl-rts-spiel-engine",level:2},{value:"Schlie\xdfen einer veralteten SSH-Verbindung",id:"schlie\xdfen-einer-veralteten-ssh-verbindung",level:2},{value:"Flachwagen Container Linux",id:"flachwagen-container-linux",level:2},{value:"Microsoft / JARVIS: ein System zur Verbindung von LLMs mit der ML-Community",id:"microsoft--jarvis-ein-system-zur-verbindung-von-llms-mit-der-ml-community",level:2},{value:"Sph\xe4rischer Tokamak erreicht entscheidende Plasmatemperaturen",id:"sph\xe4rischer-tokamak-erreicht-entscheidende-plasmatemperaturen",level:2},{value:"Die ersten &quot;Ostereier&quot; im Spiel waren ein Akt der Rebellion gegen die Unternehmen",id:"die-ersten-ostereier-im-spiel-waren-ein-akt-der-rebellion-gegen-die-unternehmen",level:2},{value:"Modulare Fehler in Rust",id:"modulare-fehler-in-rust",level:2},{value:"68-95-99.7-Regel",id:"68-95-997-regel",level:2},{value:"UnicodePlots",id:"unicodeplots",level:2},{value:"Digitale Sammlerst\xfccke auf Instagram gehen zu Ende",id:"digitale-sammlerst\xfccke-auf-instagram-gehen-zu-ende",level:2},{value:"Das Urteil, das die Zukunft der Bibliotheken bedroht",id:"das-urteil-das-die-zukunft-der-bibliotheken-bedroht",level:2},{value:"Do Kwon konvertierte illegale Gelder von LUNA in Bitcoin",id:"do-kwon-konvertierte-illegale-gelder-von-luna-in-bitcoin",level:2},{value:"Interview mit Andrew Kelley (Sch\xf6pfer von Zig) (2021)",id:"interview-mit-andrew-kelley-sch\xf6pfer-von-zig-2021",level:2},{value:"Supavisor - ein in Elixir geschriebener Postgres-Verbindungspooler",id:"supavisor---ein-in-elixir-geschriebener-postgres-verbindungspooler",level:2},{value:"Neue Plagiatsvorw\xfcrfe gegen Roy Lichtenstein",id:"neue-plagiatsvorw\xfcrfe-gegen-roy-lichtenstein",level:2}];function h(e){const n={a:"a",del:"del",h1:"h1",h2:"h2",header:"header",p:"p",...(0,s.R)(),...e.components};return(0,t.jsxs)(t.Fragment,{children:[(0,t.jsx)(n.header,{children:(0,t.jsx)(n.h1,{id:"2023-04-10",children:"2023-04-10"})}),"\n",(0,t.jsx)(n.h2,{id:"der-llama-effekt-leck-l\xf6ste-eine-reihe-von-open-source-alternativen-zu-chatgpt-aus",children:"Der LLama-Effekt: Leck l\xf6ste eine Reihe von Open-Source-Alternativen zu ChatGPT aus"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://thesequence.substack.com/p/the-llama-effect-how-an-accidental",children:"Original"}),'.\nDas versehentliche Durchsickern von "Llama", einem LLM-Modell, hat eine Open-Source-Alternativbewegung zu Modellen wie GPT-4 und Cohere ausgel\xf6st, die nur \xfcber APIs verf\xfcgbar sind. Seit dem Leck sind unter anderem Alpaca, Vicuna, Koala, ColossalChat und ChatLLama ver\xf6ffentlicht worden, die alle auf Llama aufbauen. Die Open-Source-Alternativen zu diesen Modellen haben bis zur Ver\xf6ffentlichung von Llama nicht das gleiche Leistungsniveau erreicht. Das Bekanntwerden von Llama hat sich als einer der gr\xf6\xdften Innovationssch\xfcbe im Open-Source-LLM-Bereich erwiesen, in dem sich ein Krieg zwischen Open-Source- und API-basierten Distributionen abzeichnet. Der Llama-Effekt hat bewiesen, dass Open Source ein praktikabler Vertriebsmechanismus f\xfcr grundlegende Modelle ist, und es gibt einige interessante Quellen f\xfcr Innovationen im LLM-Bereich.']}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35504428",children:"Discussion Service"}),".\nDas LLama-Effekt-Leck hat Open-Source-Alternativen zu ChatGPT hervorgebracht, die die Aufmerksamkeit von Technikexperten auf sich gezogen haben. GPT-4 beweist mehr Intelligenz und bietet Argumentations- und Verallgemeinerungsf\xe4higkeiten als sein Vorg\xe4nger, GPT-3. Reine KI-Textmodelle k\xf6nnen r\xe4umlich denken und R\xe4tsel verstehen, doch ist eine manuelle Feinabstimmung erforderlich. Es gibt eine Debatte \xfcber das tats\xe4chliche Lernniveau von Sprachmodellen, die auf eine zug\xe4ngliche und demokratisierte KI-Zukunft hoffen. Das LLaMA-Leck hat zu einer Open-Source-Optimierung auf allen Plattformen gef\xfchrt; Experten kritisieren jedoch Softwarepiraterie und die Regulierung durch KI-Unternehmen. OpenAI k\xf6nnte mit rechtlichen Herausforderungen konfrontiert werden, wenn es Modelle zum Trainieren kommerzieller Ergebnisse verwendet. Bei der ChatGPT-Genauigkeit gehen die Meinungen auseinander: Einige halten sie f\xfcr unbrauchbar, w\xe4hrend andere behaupten, GPT-4 verbessere sich in einigen Aspekten. Bing/Sydney und ChatGPT haben unterschiedliche Pers\xf6nlichkeiten. Der Beitrag enth\xe4lt keine neuen technologischen Fakten, sondern er\xf6rtert das Wesen der Textkompression."]}),"\n",(0,t.jsx)(n.h2,{id:"von-tiefem-zu-langem-lernen",children:"Von tiefem zu langem Lernen?"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://hazyresearch.stanford.edu/blog/2023-03-27-long-learning",children:"Original"}),".\nStanford-Forscher des Hazy Research Labs verbessern die Sequenzl\xe4nge in den Grundmodellen des maschinellen Lernens und konzentrieren sich dabei auf die Erstellung nahezu linearer Zeitmodelle f\xfcr die Sequenzl\xe4nge, die zu Kontextl\xe4ngen von Millionen oder sogar Milliarden f\xfchren k\xf6nnen. Das Hyena-Modell ist in der Sequenzl\xe4nge bis zu 2k skalierbar, wobei ein kleines neuronales Netz verwendet wird, das die Faltungsfilter implizit \xfcber ein weiteres kleines neuronales Netz mit einer Implementierungszeit von O(NlogN) parametrisiert. Die Forscher erforschen Lernmatrizen und ihre Verbindung zu Sprachanwendungen. N/A."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35502187",children:"Discussion Service"}),".\nStanford-Forscher erforschen Kostenreduzierung f\xfcr Selbstaufmerksamkeit in langen Sequenzen. Die Optimierung von Berechnungen f\xfcr GPUs und Co-Prozessoren kann LLMs optimieren. Skepsis gegen\xfcber Modellen mit l\xe4ngeren Kontexten, Kopplung von LLMs mit anderen Systemen kann neue L\xf6sungen schaffen. Die Ver\xf6ffentlichung von GPT-4 f\xfchrt zu neuen Forschungsarbeiten \xfcber die Vorhersage des n\xe4chsten Tokens und zu m\xf6glichen Durchbr\xfcchen im assoziativen Langzeitspeicher. Das Verst\xe4ndnis der K,Q,V-Darstellung ist entscheidend, w\xe4hrend RNNs und Transformatoren Auswirkungen auf die Demokratisierung der KI haben. L\xe4ngere Kontextl\xe4ngen k\xf6nnen als eine neue Form der Suche betrachtet werden."]}),"\n",(0,t.jsx)(n.h2,{id:"ey-wird-von-neuen-wirtschaftspr\xfcfungsunternehmen-in-deutschland-ausgeschlossen",children:"EY wird von neuen Wirtschaftspr\xfcfungsunternehmen in Deutschland ausgeschlossen"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://www.economist.com/business/2023/04/05/ey-gets-banned-from-new-audit-business-in-germany",children:"Original"}),".\nEY wurde f\xfcr zwei Jahre von der Pr\xfcfung neuer b\xf6rsennotierter Kunden in Deutschland ausgeschlossen, nachdem die APAS, die deutsche Aufsichtsbeh\xf6rde f\xfcr Rechnungslegung, eine Geldstrafe in H\xf6he von 500.000 Euro und die bisher h\xe4rteste Strafe verh\xe4ngt hatte. Die Entscheidung, die nach einer dreij\xe4hrigen Untersuchung der Rolle von EY im Wirecard-Skandal getroffen wurde, hat dem angeschlagenen Wirtschaftspr\xfcfungsriesen einen erheblichen finanziellen und rufsch\xe4digenden Schlag versetzt. EY hatte Wirecard bis zum Zusammenbruch des Unternehmens im Jahr 2020 unter dem Vorwurf des massiven Finanzbetrugs ein gutes Zeugnis ausgestellt. Nach dem Wirecard-Skandal hat EY angeblich drei Jahre lang bis zu 2 Mrd. USD f\xfcr die Verbesserung von Pr\xfcfungen in Bezug auf Technologie und Betrugsaufdeckung ausgegeben, aber kein Wirtschaftspr\xfcfer wird wohl jedes Mal alles richtig machen."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35501937",children:"Discussion Service"}),'.\nErnst & Young (EY) wurde wegen falscher Pr\xfcfungsentscheidungen und der Verwicklung in den Wirecard-Skandal von der Durchf\xfchrung neuer Pr\xfcfungen in Deutschland ausgeschlossen. Beratungsunternehmen vergeben Unterauftr\xe4ge an schlechter bezahlte Mitarbeiter, um das Risiko zu minimieren, aber das kann nach hinten losgehen. Wirtschaftspr\xfcfer bieten nur eine angemessene Sicherheit und garantieren nicht, dass kein Betrug vorliegt. Der Einsatz von Automatisierung und KI kann helfen, betr\xfcgerische Aktivit\xe4ten aufzudecken. Die Wirtschaftspr\xfcfung sollte von der Beratung getrennt werden, um Interessenkonflikte zu vermeiden. Es gibt eine Debatte \xfcber den Wert von Beratungsunternehmen und die Notwendigkeit von "Haut im Spiel".']}),"\n",(0,t.jsx)(n.h2,{id:"sonnenuntergang-am-s\xfcdpol",children:"Sonnenuntergang am S\xfcdpol"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://brr.fyi/posts/sunset",children:"Original"}),'.\nAn der S\xfcdpolstation dreht sich die Sonne in einem nahezu perfekten Kreis gegen den Uhrzeigersinn um den Himmel und macht keinen Unterschied zwischen "Nacht" und "Tag". Das hat zur Folge, dass sich der Sonnenuntergang \xfcber mehrere Wochen erstreckt und die Temperatur rapide sinkt, wenn die Sonne tief am Himmel steht, in der Regel um Mitte Februar. Der Beitrag enth\xe4lt Fotos von Sonnenuntergangsansichten aus verschiedenen Richtungen sowie ein Video, das das seltsame Ph\xe4nomen veranschaulicht. Die Station h\xe4lt sich auch an die Sommerzeit, obwohl es keinen sichtbaren Unterschied zwischen den Uhrzeiten an einem bestimmten Tag gibt. Der Beitrag informiert dar\xfcber, dass sich die S\xfcdpolstation nach der neuseel\xe4ndischen Zeit richtet, und enth\xe4lt weitere Daten wie die D\xe4mmerungsphasen und die erste Sternensichtung der Saison.']}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35500966",children:"Discussion Service"}),".\nEin Beitrag von Hacker News zeigt sch\xf6ne Fotos vom Sonnenuntergang vor einer 6-monatigen Polarnacht. In den Kommentaren wird der Umgang mit dem Mangel an Sonnenlicht, die Regulierung des Lichts und der Bau von wissenschaftlichen Einrichtungen diskutiert. Solargraphie-Experiment gescheitert. Der Bau einer Anlage am S\xfcdpol ist beeindruckend. Diskussion \xfcber die bizarren Ph\xe4nomene der Kreisbewegung der Sonne und ihre Auswirkungen auf die Lebensbedingungen. Die Antarktis ist unwirtlich und man muss um einen Platz k\xe4mpfen, um den Sonnenauf- und -untergang zu sehen. In den Kommentaren wird auch die Schwierigkeit des Atmens bei extremer K\xe4lte angesprochen. Der Artikel bietet eine interessante Perspektive auf das Leben und die Forschung in der Antarktis."]}),"\n",(0,t.jsx)(n.h2,{id:"niederl\xe4ndischer-journalist-der-kritisch-\xfcber-china-schreibt-wird-eingesch\xfcchtert",children:"Niederl\xe4ndischer Journalist, der kritisch \xfcber China schreibt, wird eingesch\xfcchtert"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://nltimes.nl/2023/04/08/dutch-journalist-writes-critically-china-targeted-bizarre-intimidation-scheme",children:"Original"}),".\nDie chinakritische niederl\xe4ndische Journalistin Marije Vlaskamp ist seit letztem Herbst Ziel eines bizarren Einsch\xfcchterungsversuchs, bei dem sie unter anderem Bombendrohungen erhielt und aufgefordert wurde, einen Artikel zur\xfcckzuziehen. Vlaskamp hat sich in der Vergangenheit kritisch \xfcber den chinesischen Staat ge\xe4u\xdfert und sich dabei insbesondere mit der Unterdr\xfcckung der Uiguren und chinesischer Dissidenten in den Niederlanden befasst. Gegen die chinesische Botschaft in Den Haag wurde eine Bombendrohung ausgesprochen, in der sowohl Vlaskamp als auch Wang Jingyu, einer der Autoren ihres Artikels, erw\xe4hnt wurden. W\xe4hrend die Angreifer von Vlaskamp nicht versuchen, den chinesischen Ursprung der Drohung zu verbergen, hat die chinesische Botschaft eine Beteiligung an der Ermutigung der Angreifer bestritten."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35501969",children:"Discussion Service"}),'.\nEin niederl\xe4ndischer Journalist wurde Opfer eines Einsch\xfcchterungsversuchs; Discussion Service-Nutzer diskutieren die chinesische Einmischung und fordern die Regierungen auf, mehr zu tun. Chinesische Polizeistationen sind in den Niederlanden und anderen L\xe4ndern t\xe4tig, und die L\xe4nder m\xfcssen m\xf6glicherweise selbst gegen so genannte "graue Aktionen" ermitteln. Kritiker argumentieren, dass Chinas Aktionen die Souver\xe4nit\xe4t verletzen, und einige Politiker wurden daraufhin bedroht. Discussion Service-Nutzer diskutieren die Rolle Chinas bei den j\xfcngsten Bombendrohungen gegen in den USA lebende Dissidenten; Debatten \xfcber Chinas Regierung und ihr Vorgehen gegen\xfcber westlichen Journalisten. ASML, ein niederl\xe4ndisches Unternehmen, taucht in einem Kontext auf, in dem China versucht, die Elektronik des Westens zu \xfcbernehmen.']}),"\n",(0,t.jsx)(n.h2,{id:"die-usps-einrichtung-in-utah-tut-nichts-anderes-als-handschriften-zu-entziffern",children:"Die USPS-Einrichtung in Utah tut nichts anderes, als Handschriften zu entziffern."}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://kutv.com/news/eye-on-utah/what-happens-to-mail-with-band-handwriting-united-states-postal-service-letter-carrier-usps-mailwoman-mailman-cursive-taught-in-schools-unreadable-print-envelopes-undeliverable-packages-salt-lake-city-utah",children:"Original"}),".\nDie USPS-Einrichtung in Utah ist auf die Entzifferung von unleserlicher Handschrift auf Post spezialisiert. In dieser Einrichtung sind \xfcber 90 Mitarbeiter besch\xe4ftigt, die die Post sortieren und mit modernster Technologie bearbeiten. Die eingesetzte Technologie kann sogar handschriftliche Adressen scannen und digitalisieren. Diese Einrichtung zeigt, wie sich die Technologie weiterentwickelt, um traditionelle Aufgaben auf innovative Weise zu erledigen."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35499641",children:"Discussion Service"}),".\nDie USPS-Einrichtung in Utah ist auf die Entzifferung von kursiver Handschrift mit einer von Eagle und Siemens bereitgestellten Software spezialisiert. Die Handschrifterkennung ist f\xfcr Postangestellte eine Herausforderung, und es ist immer noch menschliches Eingreifen erforderlich. In der Diskussion auf Hacker News geht es um die Entwicklung von Arbeit und L\xf6hnen, Eigentum, staatliche Subventionen und die Vorteile des Schreibens in B\xfcchern. Es wird vermutet, dass die Mormonengemeinde von Salt Lake City dazu beigetragen hat, dass die Einrichtung \xfcber eine gro\xdfe Anzahl von qualifizierten Lesern verf\xfcgt. Einige schlagen vor, dass der USPS eine mobile App entwickeln sollte, w\xe4hrend andere Bedenken \xfcber die Verletzung der Privatsph\xe4re durch die Verwendung privater Daten \xe4u\xdfern."]}),"\n",(0,t.jsx)(n.h2,{id:"apple-setzt-seine-bem\xfchungen-fort-eine-gewerkschaftliche-organisierung-von-einzelhandelsgesch\xe4ften-zu-verhindern",children:"Apple setzt seine Bem\xfchungen fort, eine gewerkschaftliche Organisierung von Einzelhandelsgesch\xe4ften zu verhindern"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://www.bloomberg.com/news/newsletters/2023-04-09/apple-aapl-continues-efforts-to-keep-retail-stores-from-unionizing-lg9gjdx2",children:"Original"}),".\nApple versucht, eine gewerkschaftliche Organisierung seiner Einzelhandelsgesch\xe4fte zu verhindern und gleichzeitig seine Produkt- und Komponentenproduktion au\xdferhalb Chinas zu diversifizieren. Das Unternehmen hat k\xfcrzlich Stellen abgebaut und eine weitere F\xfchrungskraft entlassen. In dem Artikel wird auch die bevorstehende Ver\xf6ffentlichung von Apples Mixed-Reality-Headset erw\xe4hnt."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35503210",children:"Discussion Service"}),".\nApple wird gewerkschaftsfeindliche Taktik vorgeworfen, einschlie\xdflich der Vorenthaltung von Leistungen; Kritik an der Verhandlungstaktik der Gewerkschaft. Diskussion \xfcber die Komplexit\xe4t der gewerkschaftlichen Organisation und die Auswirkungen auf die Arbeitnehmer. Gallup-Umfrage zeigt wachsendes Interesse an einer gewerkschaftlichen Organisierung, insbesondere bei den Besch\xe4ftigten der ersten Reihe. Einige kritisieren die niedrige Entlohnung und den Mangel an Sozialleistungen im Einzelhandel, w\xe4hrend andere argumentieren, dass sich Bef\xf6rderungen und Entlassungen, die auf der Dauer der Betriebszugeh\xf6rigkeit basieren, negativ auf die Unternehmen auswirken k\xf6nnten."]}),"\n",(0,t.jsx)(n.h2,{id:"plrust-10-jetzt-eine-vertrauensw\xfcrdige-sprache-f\xfcr-postgres",children:"PL/Rust 1.0: jetzt eine vertrauensw\xfcrdige Sprache f\xfcr Postgres"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://tcdi.github.io/plrust/plrust.html",children:"Original"}),'.\nPL/Rust ist eine ladbare prozedurale Sprache, die es erlaubt, PostgreSQL-Funktionen in Rust zu schreiben, wobei der Zugriff auf Postgres\' Server-Programmierschnittstelle und sichere Rust-Typen \xfcber die meisten von Postgres eingebauten Datentypen erm\xf6glicht wird; PL/Rust-Funktionen werden in nativen Maschinencode kompiliert, anstatt interpretiert zu werden, was die beste Leistung bietet. PL/Rust ist jetzt eine vertrauensw\xfcrdige prozedurale Sprache f\xfcr Postgres auf x86_64- und aarch64-Systemen, wenn die entsprechenden Kompilierungsanforderungen erf\xfcllt sind, was PL/Rust erlaubt, in einem Universum von Safe Rust zu leben; PL/Rust verwendet seinen eigenen rustc-Treiber, um benutzerdefinierte Lints auf die LANGUAGE-Rust-Funktion eines Benutzers anzuwenden, um bestimmte Code-Idiome anzuwenden, von denen sie wissen, dass sie keine "I-Unsound"-Probleme haben. Standardm\xe4\xdfig f\xfchrt PL/Rust keine Cross-Kompilierung durch, aber es muss installiert und durch Konfiguration aktiviert werden.']}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35501065",children:"Discussion Service"}),".\nPL/Rust 1.0 vertraut jetzt auf Postgres als Alternative f\xfcr Datenbankfunktionen. Die Cloud-Anbieter RDS und Supabase erm\xf6glichen die Implementierung von PL/Rust. Hat au\xdfergew\xf6hnliche Leistung, ist aber immer noch anf\xe4llig f\xfcr Probleme. Event-Trigger und DO-Bl\xf6cke wurden noch nicht integriert. Rust hat Zugang zum Dev-\xd6kosystem, effiziente Typen und bessere Leistung. Kann die Optimierung f\xfcr computergest\xfctzte Ausl\xf6ser einschr\xe4nken."]}),"\n",(0,t.jsx)(n.h2,{id:"twitter-blockiert-likes-und-retweets-die-substack-erw\xe4hnen",children:"Twitter blockiert Likes und Retweets, die Substack erw\xe4hnen"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://flipboard.social/@Flipboard/110161362001035875",children:"Original"}),".\nN/A."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35502684",children:"Discussion Service"}),".\nTwitter blockiert Likes/Retweets, in denen Substack erw\xe4hnt wird, was zu einem Streisand-Effekt f\xfchrt. Elon Musk beschuldigt Substack, die Twitter-Datenbank zu scrapen, Experten halten die Aussage f\xfcr unsinnig. Substack bestreitet missbr\xe4uchliche Nutzung von Twitter-APIs. Kritik an den Suchergebnissen, Verboten und API-Nutzungsrichtlinien von Twitter. Bedenken \xfcber die Qualit\xe4t der Substack-Newsfeed-Funktion. Konkurrierende Twitter und Substack entwickeln sich, alternative Microblogging-Protokolle werden untersucht. Widerstand dagegen, das Thema in ein Spektakel zu verwandeln, Ruf nach Verantwortlichkeit der F\xfchrung. Anhaltende Debatten \xfcber API-Missbrauch und das angebliche Scraping von Twitter-Inhalten durch Substack. Warnung davor, die Notlage der entlassenen Substack-Mitarbeiter zu ignorieren."]}),"\n",(0,t.jsx)(n.h2,{id:"z-library-l\xe4sst-nutzer-physische-b\xfccher-teilen",children:"Z-Library l\xe4sst Nutzer physische B\xfccher teilen"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://torrentfreak.com/z-library-plans-to-let-users-share-physical-books-through-z-points-230408/",children:"Original"}),'.\nZ-Library, das gr\xf6\xdfte Repository f\xfcr raubkopierte B\xfccher, erweitert seine Dienste um einen Markt f\xfcr physische B\xfccher, auf dem Millionen von Nutzern Taschenb\xfccher an speziellen "Z-Points" auf der ganzen Welt abholen k\xf6nnen. Es ist geplant, "Sammel- und Lagerstellen" f\xfcr B\xfccher einzurichten, die "das Bindeglied zwischen denjenigen, die ihre B\xfccher teilen, und denjenigen, die sie brauchen, sein werden", was einen betr\xe4chtlichen Lagerraum und organisatorischen Aufwand erfordert, so dass Fulfillment-Zentren und Logistikdienste Dritter willkommen sind. Eine auf der Website ver\xf6ffentlichte Ank\xfcndigung scheint ernst gemeint zu sein, denn es wurden Vietnam, Brasilien, Portugal, Kolumbien, Iran, Usbekistan, Nigeria, Spanien, Indien, Argentinien, \xc4gypten, Frankreich, \xc4thiopien, China und Ghana als ideale Z-Point-Standorte vorgeschlagen, und die Website bittet derzeit um R\xfcckmeldungen, um ihren Service zu verbessern.']}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35499065",children:"Discussion Service"}),".\nZ-Library wird es Nutzern erm\xf6glichen, physische B\xfccher zu teilen, aber Verleger k\xf6nnten die Bibliothek verklagen; einige schlagen vor, B\xfccher zu scannen, das Urheberrecht zu \xe4ndern oder Anreize zum Scannen von B\xfcchern zu schaffen. Einige diskutieren \xfcber die Durchf\xfchrbarkeit und die Auswirkungen auf die Verlage, wenn ein echter Markt f\xfcr die gemeinsame Nutzung von B\xfcchern geschaffen wird. E-Book-Lizenzierungsmodelle haben ungl\xfcckliche Folgen und f\xfchren zu Piraterie als Form des Protests. Private Mitgliedsbibliotheken sind Vorl\xe4ufer der \xf6ffentlichen Bibliotheken und werden oft ausgeliehen."]}),"\n",(0,t.jsx)(n.h2,{id:"perseus---nextjs-alternative-in-rust",children:"Perseus - NextJS-Alternative in Rust"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://framesurge.sh/perseus/en-US/",children:"Original"}),".\nPerseus ist ein Rust-Framework f\xfcr moderne Webanwendungen, das den Zustand bei Bedarf generiert und an Sycamore weitergibt, mit Fluent-basiertem I18n f\xfcr mehrsprachige Funktionalit\xe4t, Plugins f\xfcr die Anpassung, alles in WebAssembly f\xfcr hohe Leistung, und exportierbar/statisch serviert, einfach zu installieren und benutzerfreundlich."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35500528",children:"Discussion Service"}),".\nBenutzer diskutieren \xfcber Perseus, eine Rust-basierte Alternative zu NextJS, wobei einige JS f\xfcr die Front-End-Entwicklung aufgrund der Rust-Werkzeuge bevorzugen. Trotzdem l\xe4sst der Vormarsch von Rust in den unteren Ebenen des JS-Stacks auf ein Potenzial f\xfcr die Einbindung von JS/TS in Rust-Frameworks wie Perseus schlie\xdfen. Es gibt Diskussionen \xfcber die Vorz\xfcge von Rust im Vergleich zu Go, wobei einige Benutzer Rust f\xfcr die Low-Level-Programmierung und andere Go f\xfcr die Web-Entwicklung als besser geeignet ansehen. Der Wert einer Programmiersprache h\xe4ngt davon ab, wo man lebt und arbeiten will. Die Ver\xf6ffentlichung von Perseus erregt die Aufmerksamkeit von technisch versierten Personen als m\xf6gliche schnellere Alternative zu Svelte, wird aber als schwierig f\xfcr den praktischen Einsatz kritisiert."]}),"\n",(0,t.jsx)(n.h2,{id:"ein-baby-gpt",children:"Ein Baby-GPT"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://twitter.com/karpathy/status/1645115622517542913",children:"Original"}),".\nN/A."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35506069",children:"Discussion Service"}),".\nEin Discussion Service-Benutzer schl\xe4gt vor, bin\xe4re regul\xe4re Ausdr\xfccke f\xfcr Sprachbeziehungen zu verwenden, w\xe4hrend ein anderer f\xfcr Bedeutung und Absicht pl\xe4diert. Der Sch\xf6pfer des Baby-GPT vergleicht es mit einer Markov-Kette. Ein Experte empfiehlt bessere mathematische Werkzeuge. Discussion Service-Benutzer fragt nach den Folgen f\xfcr die Allgemeinheit. Keine nennenswerten neuen Technologien oder Ver\xf6ffentlichungen."]}),"\n",(0,t.jsx)(n.h2,{id:"zwei-arten-von-software-ingenieuren",children:"Zwei Arten von Software-Ingenieuren"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://registerspill.thorstenball.com/p/two-types-of-software-engineers",children:"Original"}),".\nDer Artikel behandelt zwei Typen von Softwareingenieuren: Typ 1, der davon ausgeht, dass ein Problem einfach ist, wenn es nicht technisch ist, und Typ 2, der davon ausgeht, dass es schwierig ist, weil es Menschen betrifft. Typ 1 glaubt an das gro\xdfe E des Engineerings, w\xe4hrend Typ 2 den Menschen in den Mittelpunkt stellt und davon ausgeht, dass technische Probleme den Menschen betreffen. W\xe4hrend Typ 1 h\xe4ufiger anzutreffen ist, verstehen Ingenieure des Typs 2, dass Technik mit Chaos und Komplexit\xe4t verbunden ist, und versuchen, trotz dieser Herausforderungen zu bauen. Der Artikel enth\xe4lt einige Beispiele zur Veranschaulichung der Unterschiede, aber der Autor hat die Grenze zwischen den beiden Typen noch nicht genau definiert oder gezogen."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35503784",children:"Discussion Service"}),".\nEine Diskussion \xfcber zwei Typen von Softwareingenieuren, einschlie\xdflich Typ 3, und die Bedeutung des Verst\xe4ndnisses von Produktmanagement. Debatte \xfcber das Gleichgewicht zwischen Innovation und Stabilit\xe4t und die Notwendigkeit einer angemessenen Dokumentation. Dichotomie zwischen dem Verlassen auf Menschen und der Implementierung automatisierter L\xf6sungen in der Softwareentwicklung. Bedeutung der Ausrichtung aller auf gemeinsame Ziele und des Verst\xe4ndnisses gr\xf6\xdferer Gesch\xe4ftsanforderungen. Die Kategorisierung von Softwareingenieuren wird in Frage gestellt, wobei der Schwerpunkt auf der Suche nach der Ursache von Problemen liegt. Der Beitrag dient als Denkansto\xdf."]}),"\n",(0,t.jsx)(n.h2,{id:"fortgeschrittene-linux-programmierung-2001",children:"Fortgeschrittene Linux-Programmierung (2001)"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://mentorembedded.github.io/advancedlinuxprogramming/",children:"Original"}),".\n'Advanced Linux Programming' von CodeSourceryLLC ist ein Buch, das GNU/Linux-Entwicklern hilft, Software mit benutzerfreundlichen Funktionen, fortgeschrittenen F\xe4higkeiten wie Multi-Threading, Interprozess-Kommunikation und Hardware-Ger\xe4te-Interaktion zu erstellen und das Programm insgesamt zu verbessern. Dar\xfcber hinaus lehrt dieses Buch Entwickler, wie man innerhalb der GNU/Linux-Systemumgebung arbeitet, einschlie\xdflich ihrer einzigartigen Einschr\xe4nkungen, Konventionen und M\xf6glichkeiten. Dieses Buch kann unter der Open Publication License, Version 1, heruntergeladen werden und bietet Zugang zu Codebeispielen unter der GNU General Public License. Errata und \xdcbersetzungen des Buches sind verf\xfcgbar."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35500197",children:"Discussion Service"}),'.\nBenutzer von Hacker News diskutieren \xfcber die Relevanz des Buches "Advanced Linux Programming" von 2001 im Jahr 2021. Einige Benutzer schlagen vor, \xfcberholte Abschnitte zu aktualisieren. Obwohl es ein Buch f\xfcr Anf\xe4nger ist, bleibt es eine n\xfctzliche Ressource f\xfcr die Entwicklung von Linux-APIs. Die Aria2 Download-Anwendung dient als Alternative zu Server-Geschwindigkeitsbegrenzungen.']}),"\n",(0,t.jsx)(n.h2,{id:"ein-cern-f\xfcr-open-source-ki-im-gro\xdfen-ma\xdfstab",children:"Ein CERN f\xfcr Open-Source-KI im gro\xdfen Ma\xdfstab"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://www.openpetition.eu/petition/online/securing-our-digital-future-a-cern-for-open-source-large-scale-ai-research-and-its-safety",children:"Original"}),".\nLAION e.V. hat eine Petition f\xfcr eine internationale, \xf6ffentlich finanzierte, quelloffene Supercomputing-Forschungseinrichtung f\xfcr KI, \xe4hnlich dem CERN, gestartet, um die KI-Forschung zu demokratisieren und die Sicherheitsforschung zu f\xf6rdern. Die Plattform openPetition will die B\xfcrgerbeteiligung st\xe4rken und Petitionen f\xfcr Ver\xe4nderungen unterst\xfctzen. Die Initiative will demokratische Prinzipien davor sch\xfctzen, von einigen wenigen Gro\xdfunternehmen untergraben zu werden. Ein Discussion Service-Nutzer stellte fest, dass 19 % der Unterst\xfctzer von laion.ai kommen, w\xe4hrend 64 % unbekannt bleiben. Die B\xfcrgerinnen und B\xfcrger werden aufgefordert, die Petition, die auf Hacker News an Fahrt gewonnen hat, durch Spenden zu unterst\xfctzen."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35501845",children:"Discussion Service"}),".\nEin Artikel auf openpetition.eu unterstreicht den Bedarf Europas an einer CERN-\xe4hnlichen Open-Source-Initiative zur F\xf6rderung der Zusammenarbeit zwischen KI-Forschern, Akademikern und Unternehmern. Die Zusammenarbeit ist notwendig, um die Verarbeitung gro\xdfer Datenmengen mit hohen Investitionen durchzuf\xfchren. Open-Source-Projekte sind notwendig, um KI-Forscher an sich zu binden und der Gesellschaft und nicht den Aktion\xe4ren der Unternehmen zu nutzen. Der Erfolg des CERN macht es zu einem attraktiven Modell, auch wenn einige meinen, der Markt biete angemessene Anreize. Die interdisziplin\xe4re Natur der KI erfordert die Ber\xfccksichtigung miteinander verbundener Themen."]}),"\n",(0,t.jsx)(n.h2,{id:"permafrost-engine---eine-in-c-geschriebene-opengl-rts-spiel-engine",children:"Permafrost-Engine - Eine in C geschriebene OpenGL-RTS-Spiel-Engine"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://github.com/eduard-permyakov/permafrost-engine",children:"Original"}),".\nDie Permafrost-Engine ist eine in C geschriebene OpenGL 3.3-Echtzeit-Strategie-Spiel-Engine, die sich an alten Klassikern orientiert, aber auch einige moderne Ideen einbezieht. EVERGLORY ist das Flaggschiffspiel, das mit der Permafrost Engine entwickelt wurde und die F\xe4higkeiten der Engine mit Spielerfahrungen aus erster Hand pr\xe4sentiert. Die Zusammenfassung der Engine enth\xe4lt eine Liste von OpenGL- und Python-Funktionen, RTS-Mechaniken und plattform\xfcbergreifenden F\xe4higkeiten. Die Lizenz f\xfcr die Permafrost Engine ist GPLv3, mit einer speziellen Linking-Ausnahme. Bauanleitungen werden sowohl f\xfcr Linux als auch f\xfcr Windows bereitgestellt. Ein Devlog und eine E-Mail f\xfcr Fragen/Kommentare zum Projekt oder zum Quellcode werden f\xfcr interessierte Benutzer bereitgestellt."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35504053",children:"Discussion Service"}),".\nDie Open-Source-Engine Permafrost erh\xe4lt auf Discussion Service Aufmerksamkeit f\xfcr ein neues Open-Source-RTS-Spiel. Die Klarheit der Schriftart von Everglory wird kritisiert. Vergleich mit anderen RTS-Engines erbeten. Tests von Entwicklern auf Handheld-Bildschirmen sind wichtig. Hoffnung auf Wiederbelebung des RTS-Genres. Benutzer diskutieren \xfcber Open-Source-RTS-Engines und verwendete Sprachen. Erw\xe4hnung einer weiteren Open-Source-Implementierung der Frostbite-Engine."]}),"\n",(0,t.jsx)(n.h2,{id:"schlie\xdfen-einer-veralteten-ssh-verbindung",children:"Schlie\xdfen einer veralteten SSH-Verbindung"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://davidisaksson.dev/posts/closing-stale-ssh-connections/",children:"Original"}),".\nDer Beitrag beschreibt, wie man eine veraltete SSH-Sitzung schlie\xdft, und erkl\xe4rt, dass die erste L\xf6sung darin bestehen k\xf6nnte, den Terminalemulator zu schlie\xdfen, dass es aber einen besseren Weg gibt, indem man die eingebauten SSH-Escape-Sequenzen verwendet. Der Beitrag erkl\xe4rt, wie das Tilde-Pr\xe4fix (",(0,t.jsx)(n.del,{children:'), gefolgt von einem Befehl, mehrere versteckte Befehle in SSH-Clients ausl\xf6sen kann, einschlie\xdflich des Befehls "terminate session" ('}),'.). Der Beitrag weist darauf hin, dass ein vorangehender Zeilenumbruch erforderlich ist, und bietet einen kleinen Hinweis f\xfcr Personen, die eine Tastatur mit nordischem Layout verwenden, um das Tilde-Zeichen einzugeben. Der Beitrag endet mit einer Diskussion dar\xfcber, was nach der Verwendung der Escape-Sequenz "terminate session" zu tun ist.']}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35504402",children:"Discussion Service"}),".\nEin Discussion Service-Benutzer gibt einen SSH-Tipp. Ein anderer weist auf ein Layout-Problem hin, bietet aber einen Workaround an. Es wird vorgeschlagen, EscapeChar zu konfigurieren. Diskussion \xfcber SSH-Manpage, springende Hosts und SSH-Verbindungen. Sticky SSH session wird gew\xfcnscht. Autossh wird f\xfcr Auto-Attach empfohlen und Mosh f\xfcr die \xc4nderung der Portweiterleitung. Verschl\xfcsselungsdetails und zus\xe4tzliche Tipps. Warnung vor der Verwendung von Alpine Linux."]}),"\n",(0,t.jsx)(n.h2,{id:"flachwagen-container-linux",children:"Flachwagen Container Linux"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://www.flatcar.org/",children:"Original"}),".\nFlatcar Container Linux ist eine Community-Linux-Distribution, die f\xfcr Container-Workloads mit hoher Sicherheit und geringem Wartungsaufwand konzipiert ist. Das Betriebssystem-Image enth\xe4lt nur die Tools, die f\xfcr den Betrieb von Containern erforderlich sind, ohne Paketmanager oder Konfigurationsdrift. Das unver\xe4nderliche Dateisystem und die automatisierten atomaren Updates bieten eine solide Grundlage f\xfcr die Sicherheit der Infrastruktur. Die integrierten Sicherheitsfunktionen von Flatcar Container Linux und die reduzierte Angriffsfl\xe4che vereinfachen die Verwaltung des Betriebssystems. Es enth\xe4lt Tools f\xfcr die Verwaltung gro\xdfer Infrastrukturen und unterst\xfctzt globale Initiativen. Automatisierte, atomare Updates stellen sicher, dass Sie die stabilste, sicherste und aktuellste Flatcar-Version einsetzen. Es ist ein direkter Ersatz f\xfcr CoreOS Container Linux."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35503928",children:"Discussion Service"}),".\nMicrosofts Flatcar Container Linux Update wird auch nach der \xdcbernahme weitergef\xfchrt und bietet eine Alternative zu CloudInit. Der unver\xe4nderliche Infrastrukturansatz gewinnt trotz der technischen Probleme von Ignition an Popularit\xe4t. Flatcar-Linux-Entwickler schlagen ein freundliches Update vor. Discussion Service-Benutzer diskutieren das Hinzuf\xfcgen von Containern und schlagen eine UEFI-Firmware f\xfcr bessere Leistung vor."]}),"\n",(0,t.jsx)(n.h2,{id:"microsoft--jarvis-ein-system-zur-verbindung-von-llms-mit-der-ml-community",children:"Microsoft / JARVIS: ein System zur Verbindung von LLMs mit der ML-Community"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://github.com/microsoft/JARVIS",children:"Original"}),".\nMicrosoft und Hugging Face haben das Labs-Projekt JARVIS vorgestellt, einen KI-Assistenten zur Verbindung von Sprach- und Machine-Learning-Modellen. JARVIS verwendet ein gro\xdfes Sprachmodell (LLM), um Anfragen zu verstehen und zu analysieren, und nutzt dann eine Auswahl zahlreicher Expertenmodelle, um die gew\xfcnschte Aufgabe auszuf\xfchren. Es besteht aus vier Phasen: Aufgabenplanung, Modellauswahl, Aufgabenausf\xfchrung und Antwortgenerierung. Der Benutzer kann JARVIS auf einfache Weise nutzen, ohne die Modelle lokal einsetzen zu m\xfcssen, indem er den CLI-Modus oder die Webseite aktiviert, die eine benutzerfreundliche Schnittstelle f\xfcr die Kommunikation mit JARVIS bietet."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35500472",children:"Discussion Service"}),".\nMicrosoft bringt JARVIS auf den Markt, um LLMs mit der ML-Gemeinschaft zu verbinden, die regelbasierte Ans\xe4tze und maschinelles Lernen nutzt. Einige spekulieren dar\xfcber, ob autonome KI-Agenten Betrug oder Schwindel begehen k\xf6nnen, doch die Leser sind \xfcberwiegend begeistert. Jarvis generiert Text und Bilder auf der Grundlage der von LLM gew\xe4hlten Modelle, aber einige \xe4u\xdfern Bedenken zu Markenfragen und zum Abh\xf6ren von Daten."]}),"\n",(0,t.jsx)(n.h2,{id:"sph\xe4rischer-tokamak-erreicht-entscheidende-plasmatemperaturen",children:"Sph\xe4rischer Tokamak erreicht entscheidende Plasmatemperaturen"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://www.eetimes.com/spherical-tokamak-achieves-crucial-plasma-temperatures/",children:"Original"}),".\nDer kugelf\xf6rmige Tokamak von Tokamak Energy hat Ionentemperaturen von \xfcber 100 Millionen Grad Kelvin erreicht - ein entscheidender Schritt bei der Entwicklung der Fusionsenergietechnologie. Die geringe Gr\xf6\xdfe, die Plasmastabilit\xe4t und die Eigenschaften des magnetischen Einschlusses von sph\xe4rischen Tokamaks machen sie zu einer attraktiven Wahl f\xfcr die kommerzielle Erzeugung von Fusionsenergie. Steven McNamara, wissenschaftlicher Direktor bei Tokamak Energy, ist der Ansicht, dass das Unternehmen die Fusionsenergie innerhalb von 10 Jahren als Erg\xe4nzung zu anderen erneuerbaren Energiequellen ans Netz bringen kann. Der Durchbruch nutzt die Thomson-Streuung zur Messung von Temperatur und Dichte an mehreren Punkten und ebnet damit den Weg f\xfcr kosteng\xfcnstige, einsatzbereite kommerzielle Fusionskraftwerke. Die Technologie kann auch in der nachhaltigen Luftfahrt und bei der Herstellung von Wasserstoff als Kraftstoff eingesetzt werden."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35505342",children:"Discussion Service"}),".\nIn einem kugelf\xf6rmigen Tokamak werden die entscheidenden Plasmatemperaturen erreicht. Einige Nutzer diskutieren strukturelle Probleme, einer empfiehlt einen Fusionsenergie-Podcast. Der Artikel erl\xe4utert die Notwendigkeit eines W\xe4rmetauschers und die geringeren Kosten der neuen Konstruktion. Die Rentabilit\xe4t der kommerziellen Fusion wird diskutiert. Die Verdoppelung der Magnetst\xe4rke in kleinen Tests bringt Fortschritte. Abfall- und Sicherheitsvorteile der Fusion gegen\xfcber der Kernspaltung werden erw\xe4hnt. Sph\xe4rische Tokamaks sind eine moderne Anwendung. Der erreichte Meilenstein ist noch nicht n\xfctzlich, aber es werden Fortschritte bei der Magnetst\xe4rke erzielt."]}),"\n",(0,t.jsx)(n.h2,{id:"die-ersten-ostereier-im-spiel-waren-ein-akt-der-rebellion-gegen-die-unternehmen",children:'Die ersten "Ostereier" im Spiel waren ein Akt der Rebellion gegen die Unternehmen'}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://thehustle.co/the-first-easter-eggs-were-an-act-of-corporate-rebellion/",children:"Original"}),'.\nDie ersten Easter Eggs in Videospielen waren das Ergebnis von Designern, denen die Anerkennung f\xfcr ihre Arbeit verweigert wurde, was zu versteckten Botschaften in Spielen f\xfchrte. Das erste Osterei wurde 1980 in Ataris Spiel "Adventure" gefunden, das von Warren Robinett entwickelt wurde. Die Tradition der versteckten Botschaften wurde in den 1970er Jahren in Arcade-Spielen fortgesetzt, um Anerkennung und Individualit\xe4t zu erreichen. Robinetts Osterei erh\xf6hte seinen Status, und er entwickelte sp\xe4ter ein erfolgreiches Softwareunternehmen. Die Tech Times berichtet \xfcber verschiedene Cookies, die von Unternehmen verwendet werden, um das Online-Verhalten von Nutzern zu verfolgen und Werbung zu personalisieren, die aber noch nicht klassifiziert wurden.']}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35503260",children:"Discussion Service"}),".\nEin Beitrag von Hacker News \xfcber die Rebellion von Unternehmen durch Ostereier enth\xe4lt Anekdoten und aktuelle Unternehmensrichtlinien. Das Interesse der Leser k\xf6nnte durch die historische Relevanz und die Entwicklung der Rolle des Ostereis geweckt werden. Aktuelle Ostereier sind Ausdruck von Unternehmensstolz, nicht von Ungehorsam. Code\xfcberpr\xfcfungen verhindern Ostereier. Ehemalige Tech-Unternehmen fallen oft unter neu ernannte MBAs. Warren Robinett wird f\xfcr Adventure game gelobt. Ein Mitglied von U2 und ein Atari-Fan haben unterschiedliche Namen."]}),"\n",(0,t.jsx)(n.h2,{id:"modulare-fehler-in-rust",children:"Modulare Fehler in Rust"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://sabrinajewson.org/blog/errors",children:"Original"}),".\nDer Artikel diskutiert die Bedeutung einer modularen Fehlerbehandlung und f\xfchrt das Prinzip ein, dass Fehlertypen in der N\xe4he ihrer Fehlbarkeitseinheit liegen, wobei eine hypothetische Rust-Bibliothek als Beispiel dient. Probleme mit nicht hilfreichen Fehlermeldungen, Unerweiterbarkeit und Schwierigkeiten bei der Fehlersuche werden umrissen und L\xf6sungen wie die .source()-Methode und eine bessere Fehlertypkonstruktion vorgeschlagen. Der Fehlertyp der Beispielbibliothek wird in drei verschiedene Typen mit guten R\xfcckverfolgungen und pr\xe4zisem Fehlerabgleich aufgeteilt, und E/A-Fehler werden durch einen besser strukturierten Fehlertypentwurf erkl\xe4rt. Der Artikel unterstreicht die Bedeutung von guten R\xfcckverfolgungen, Erweiterbarkeit, Pr\xfcfbarkeit, Stabilit\xe4t und Modularit\xe4t bei der Fehlerbehandlung und legt nahe, dass es sich lohnt, eine gute Fehlerbehandlung zu erlernen."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35502874",children:"Discussion Service"}),".\nDie Fehlermeldungen von Rust sind beliebt, aber es werden verschiedene Fehlertypen ben\xf6tigt. SNAFU erm\xf6glicht es, eindeutige Spuren zu erzeugen. Eindeutige Fehler reduzieren die Verbreitung und machen die Handhabung einfacher, aber man sollte sich vor der Unterst\xfctzung \xf6ffentlicher APIs h\xfcten. Das Protokollieren und Beenden sollte nicht der prim\xe4re Ansatz f\xfcr das Debuggen von Bibliotheken sein. Granulare oder undurchsichtige Fehler mit Beschreibungen sind vorzuziehen. Gepr\xfcfte Ausnahmen in Java werden gelobt. Der fatale Fehler von Java ist, dass es keine algebraischen Typen gibt."]}),"\n",(0,t.jsx)(n.h2,{id:"68-95-997-regel",children:"68-95-99.7-Regel"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://en.wikipedia.org/wiki/68%E2%80%9395%E2%80%9399.7_rule",children:"Original"}),".\nDie 68-95-99,7-Regel ist ein statistischer N\xe4herungswert, der den Prozentsatz der Werte innerhalb einer Standardabweichung vom Mittelwert in der Normalverteilung sch\xe4tzt. Die Regel besagt, dass ungef\xe4hr 68 %, 95 % und 99,7 % innerhalb von einer, zwei bzw. drei Standardabweichungen liegen. Diese Regel findet in verschiedenen Bereichen Anwendung, z. B. bei der Qualit\xe4tskontrolle und der Datenanalyse. Sie ist eine schnelle Methode, um eine grobe Wahrscheinlichkeitssch\xe4tzung f\xfcr eine als normal angenommene Population zu erhalten. Die Formel kann auf verschiedene Verteilungen angewandt werden, und sie kann bei der Datenanalyse helfen, Ausrei\xdfer zu erkennen."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35501780",children:"Discussion Service"}),".\nIn den Discussion Service-Kommentaren werden die Grenzen der 68-95-99,7-Regel bei der Datenanalyse er\xf6rtert. Die Arbeit von Nassim Nicholas Taleb und die Tschebyscheffsche Ungleichung werden erw\xe4hnt. Anmerkungen zum Finanzhandel und zur Geschichte des US-Optionsmarktes. Experten behaupten, hohe IQ-Werte seien unzuverl\xe4ssig und die Skala sei willk\xfcrlich."]}),"\n",(0,t.jsx)(n.h2,{id:"unicodeplots",children:"UnicodePlots"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://github.com/JuliaPlots/UnicodePlots.jl",children:"Original"}),".\nDie UnicodePlots-Bibliothek ist ein High-Level-Plotting-Tool f\xfcr die Verwendung in der REPL von Julia, das Streudiagramme, Liniendiagramme und Heatmaps enth\xe4lt. Sie unterst\xfctzt auch physikalische Gr\xf6\xdfen aus Unitful.jl und Intervalle aus IntervalSets.jl, erm\xf6glicht die Anpassung von Plot-Funktionen wie Plot-H\xf6he und -Breite sowie das Umkehren/Spiegeln von Plot-Achsen und unterst\xfctzt das Speichern von Plots als PNG oder TXT."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35505591",children:"Discussion Service"}),".\nDas auf Julia basierende UnicodePlots zeigt Diagramme und Histogramme auf dem Terminal f\xfcr schnelle Visualisierungen auf entfernten Servern an. Es entspricht dem Bed\xfcrfnis nach schneller Datenvisualisierung im Terminal, ohne einen vollst\xe4ndigen Grafik-Stack zu installieren. UnicodePlots wurde gr\xf6\xdftenteils in eine Ruby-Portierung und eine Python-Version kopiert, die mit Matplotlib kompatibel ist. Derzeit gibt es einen Trend zu Text-Benutzeroberfl\xe4chen, der eine Aufteilung zwischen Electron f\xfcr Endbenutzeranwendungen und TUI f\xfcr portable Tools schafft. Es hat eine 100%ige Codeabdeckung, unterst\xfctzt vergleichende Histogramme und erm\xf6glicht es den Benutzern, Daten direkt in Kommentare oder Beschreibungen zu kopieren und einzuf\xfcgen. Obwohl es sich nicht um eine v\xf6llig neue Technologie handelt, ist UnicodePlots ein n\xfctzliches Werkzeug f\xfcr diejenigen, die Daten schnell auswerten m\xfcssen."]}),"\n",(0,t.jsx)(n.h2,{id:"digitale-sammlerst\xfccke-auf-instagram-gehen-zu-ende",children:"Digitale Sammlerst\xfccke auf Instagram gehen zu Ende"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://help.instagram.com/1824155514623095",children:"Original"}),".\nAb dem 11. April 2023 wird Instagram seine Unterst\xfctzung f\xfcr digitale Sammlerst\xfccke einstellen, was sich auf die Erstellung neuer digitaler Sammlerst\xfccke, die Sichtbarkeit digitaler Geldb\xf6rsen und die Zug\xe4nglichkeit von Blockchain-Informationen auswirken wird. Die L\xf6schung der Daten digitaler Sammlerst\xfccke erfolgt in \xdcbereinstimmung mit der Datenschutzrichtlinie von Instagram und den Nutzungsbedingungen f\xfcr digitale Sammlerst\xfccke, aber die Nutzer k\xf6nnen vor Ablauf der Frist einen Antrag auf Herunterladen ihrer Daten stellen. Die Inhalte digitaler Geldb\xf6rsen von Drittanbietern sind davon nicht betroffen."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35501074",children:"Discussion Service"}),'.\nDie digitalen Sammlerst\xfccke von Instagram verlieren an Fahrt, aber die Anh\xe4nger von web3 lassen sich nicht abschrecken. Der NFT-Bereich muss sich mit Eigentumsstandards und der \xdcbernahme durch Unternehmen befassen. Die Avatare von Reddit verkaufen sich gut, obwohl Polygon-NFTs als weniger wertvoll angesehen werden. Der Winter wird von Bauherren zum Aufbau von Infrastrukturen und von traditionellen Unternehmen zum Kennenlernen dezentraler Netzwerke begr\xfc\xdft. Der Erfolg von Pokemon-Karten und Reddit-Features wird mit dem Konzept der Knappheit verglichen. Der Begriff "Web3" mag verfr\xfcht sein, und Gauner und Bauherren sind in unterschiedlichen Lagern. Es gibt Skepsis und Bedenken hinsichtlich des NFT-Hypes, der Investitionsrisiken und der psychischen Gesundheit. Kultische Verstrickungen in Branchen, Kryptow\xe4hrungen und KI-Risiken werden diskutiert. Die N\xfctzlichkeit von ChatGPT wird debattiert, und die Nutzer konzentrieren sich auf neue Erkenntnisse ohne politische oder religi\xf6se Sprache. Der Kontext fortschrittlicher Technologie in Bezug auf Kommunikation und Erdsynchronisation wird diskutiert, wobei es unterschiedliche Meinungen \xfcber den Wert der NFT und ihre Auswirkungen auf die Gesellschaft gibt.']}),"\n",(0,t.jsx)(n.h2,{id:"das-urteil-das-die-zukunft-der-bibliotheken-bedroht",children:"Das Urteil, das die Zukunft der Bibliotheken bedroht"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://www.theatlantic.com/ideas/archive/2023/04/internet-archive-libraries-federal-court-ruling/673615/",children:"Original"}),'.\nEin Bundesgerichtsurteil, das besagt, dass die kontrollierte digitale Ausleihe (CDL) gegen das Urheberrecht verst\xf6\xdft, k\xf6nnte katastrophale Folgen f\xfcr Bibliotheken haben, die sich nun entscheiden m\xfcssen, ob sie teure Ebook-Lizenzen von Verlagen erwerben oder ihre Sammlungen erweitern. Das Internet Archive (IA), eine gemeinn\xfctzige Organisation, die digitale Kopien der Millionen von B\xfcchern ausleiht, die sie gesammelt und digitalisiert hat, stand im Mittelpunkt einer Klage mehrerer Buchverlage, die sie 2020 wegen Urheberrechtsverletzung verklagten; Und es war dieses CDL-Verleihmodell, gegen das das Gericht im vergangenen Monat entschieden hat. Es k\xf6nnte "unfairen Einfluss auf die Zukunft von B\xfcchern und Bibliotheken gleicherma\xdfen haben", so die Anw\xe4ltin Corynne McSherry von der Electronic Frontier Foundation, die die IA bei ihrer Berufung gegen das Urteil vertritt.']}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35502238",children:"Discussion Service"}),".\nDas Gerichtsurteil \xfcber die kontrollierte digitale Ausleihe und die Urheberrechtsgesetze hat Debatten ausgel\xf6st, wobei vorgeschlagen wurde, die Dauer des Urheberrechts zu verk\xfcrzen, um den Verlust von Wissen zu verhindern; einige schlagen vor, dass die Gewinne der Verleger beim Verleih von CDL-Material nicht das Thema sein sollten. Bibliotheken haben sich zu \xf6ffentlichen Unterhaltungszentren entwickelt, und der \xf6ffentliche Zugang zu Ressourcen ist von entscheidender Bedeutung; Bibliothekare nutzen Expertenmeinungen, um bei der Aussonderung von B\xfcchern die Beliebtheit der Auflage, den Wert des Buches und die Aufgabe der Bibliothek abzuw\xe4gen. Klagen von Verlegern gegen den unbegrenzten, geb\xfchrenfreien digitalen Vertrieb des Internet Archive gef\xe4hrden die Eink\xfcnfte der Autoren, und die kontrollierte digitale Ausleihe k\xf6nnte den Schutz des Urheberrechts gef\xe4hrden. Die \xdcberschneidung von digitalem und physischem Eigentum ist nach wie vor umstritten; die Diskussionen bieten einzigartige Perspektiven zu diesem Thema."]}),"\n",(0,t.jsx)(n.h2,{id:"do-kwon-konvertierte-illegale-gelder-von-luna-in-bitcoin",children:"Do Kwon konvertierte illegale Gelder von LUNA in Bitcoin"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://cointelegraph.com/news/do-kwon-converted-stolen-funds-from-luna-to-bitcoin-s-korean-prosecutors",children:"Original"}),".\nS\xfcdkoreanische Staatsanw\xe4lte haben illegale Verm\xf6genswerte im Wert von fast 314,2 Millionen Dollar identifiziert, die mit dem Mitbegr\xfcnder von Terraform Labs, Do Kwon, und seinen Partnern in Verbindung gebracht werden, von denen Kwon allein etwa 69 Millionen Dollar besitzt. Die Staatsanwaltschaft hat Binance aufgefordert, alle Abhebungsantr\xe4ge im Zusammenhang mit Kwon zu stoppen. Kwon hat Berichten zufolge den Gro\xdfteil der illegalen Gelder, die sich auf rund 414,5 Milliarden Won belaufen, in Bitcoin umgewandelt, und keines der Verm\xf6genswerte, die mit ihm in Verbindung stehen, ist wiederherstellbar oder unter der Zust\xe4ndigkeit der s\xfcdkoreanischen Beh\xf6rden. Terra war ein Krypto-\xd6kosystem, das im Mai 2022 zusammenbrach und bei dem der ehemalige CEO Kwon beschuldigt wurde, nach dem Zusammenbruch Bitcoin im Wert von fast 100 Millionen Dollar abgezweigt zu haben."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35499996",children:"Discussion Service"}),".\nOn-Chain-Daten zeigen, dass Do Kwon von Terraform Labs betr\xfcgerische LUNA-Gelder in Bitcoin umgewandelt hat. Zeigt die Grenzen der Verfolgung von Betrug durch traditionelle Banken auf. Discussion Service-Nutzer diskutieren \xfcber Datenschutz-Tools und Ehrlichkeit im Krypto-Bereich. Debatte dar\xfcber, ob sich Intelligenz f\xfcr den Wettbewerb oder f\xfcr die Zusammenarbeit entwickelt hat, wobei einige f\xfcr Letzteres pl\xe4dieren. Wettbewerb und Raubbau treiben den Wettbewerb an, aber der allgemeine Trend geht dahin, die Rollen in der Intelligenzentwicklung weiter zu diskutieren."]}),"\n",(0,t.jsx)(n.h2,{id:"interview-mit-andrew-kelley-sch\xf6pfer-von-zig-2021",children:"Interview mit Andrew Kelley (Sch\xf6pfer von Zig) (2021)"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://corecursive.com/067-zig-with-andrew-kelley/",children:"Original"}),".\nAndrew Kelley spricht \xfcber seine Erfahrungen bei der Entwicklung der Programmiersprache Zig, \xfcber die Herausforderungen, einen Vollzeitjob mit Open-Source-Arbeit zu vereinbaren, \xfcber die Bedeutung von Verhandlungen \xfcber das Eigentum an geistigem Eigentum und \xfcber die moralischen Fragen im Zusammenhang mit kommerziellem Forking in der Open-Source-Gemeinschaft. Zig ist eine gemeinn\xfctzige Programmiersprache, die die Speichersicherheit verbessern und die Informationsflut f\xfcr die Benutzer verringern soll. Kelley hat die Vision, dass Zig die Sprache der Wahl f\xfcr Betriebssysteme und Lehrb\xfccher wird und zu einer besseren Anwendungsleistung, Speichernutzung und Stabilit\xe4t f\xfchrt. Tech Times berichtet auch \xfcber verschiedene online verf\xfcgbare Videokurse zum Thema Programmierung."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35502151",children:"Discussion Service"}),".\nDas Interview von Corecursive mit Zig-Sch\xf6pfer Andrew Kelley regt die H\xf6rer dazu an, alle bisherigen Podcasts auf der Website herunterzuladen, und diskutiert in separaten Kommentaren \xfcber Crowdfunding-Projekte und pers\xf6nliche Ratschl\xe4ge. Ein H\xf6rer sch\xe4tzt die freundliche Atmosph\xe4re im Kanal #chicken scheme. Ein anderer hebt die Transparenz von Andrew Kelley bei einem Forked-Zig-Vorfall hervor, aber ein Nutzer reagiert negativ auf seine Interaktion mit Kelley. Insgesamt gef\xe4llt den Zuh\xf6rern die Berichterstattung \xfcber Zig und die technische Geschichte von SQLite im Interview."]}),"\n",(0,t.jsx)(n.h2,{id:"supavisor---ein-in-elixir-geschriebener-postgres-verbindungspooler",children:"Supavisor - ein in Elixir geschriebener Postgres-Verbindungspooler"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://github.com/supabase/supavisor",children:"Original"}),".\nSupavisor ist ein Postgres-Verbindungspooler, der Millionen von Postgres-End-Client-Verbindungen in einen zustandsabh\xe4ngigen Pool nativer Postgres-Datenbankverbindungen \xfcber eine skalierbare, Cloud-native Architektur umwandeln kann. Dieses System vereinfacht die Verwaltung von Postgres-Clustern f\xfcr Datenbankmanager, indem es eine einfache Konfiguration von hochverf\xfcgbaren Postgres-Clustern erm\xf6glicht und gleichzeitig ressourceneffizient, skalierbar, mandantenf\xe4hig und Cloud-nativ ist. Es gibt bereits Benchmarks und Lasttests, die zeigen, dass es eine Million Postgres-Verbindungen auf einem Cluster handhaben und Millionen von Verbindungen aufnehmen kann, was es zu einer gro\xdfartigen Wahl f\xfcr Entwickler macht, die sich mit Postgres aus Serverless-Umgebungen verbinden. Zuk\xfcnftige Arbeiten umfassen Load Balancing, Session Pooling, Postgres Hochverf\xfcgbarkeitsmanagement und APIs wie Postgres Binary, HTTPS und vieles mehr. Jos\xe9 Valim und das Dashbit-Team haben bei den Design-Entscheidungen f\xfcr Supavisor mitgeholfen, und es wurde von Produkten wie PgBouncer, Amazon RDS Proxy, Google Cloud SQL Proxy und anderen inspiriert."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35501718",children:"Discussion Service"}),".\nDer CEO von Supabase stellt Supavisor vor, einen Postgres-Verbindungspooler, der mit Elixir entwickelt wurde, und hebt dessen \xc4hnlichkeit mit Pgbouncer hervor, der f\xfcr Multi-Tenancy ausgelegt ist. Supavisors Benchmarks zeigen, dass er einen hohen Durchsatz bew\xe4ltigen kann, w\xe4hrend er 7,8G RAM und ~50% CPU auf einer 64vCPU-Maschine verbraucht. Supabase plant, Supavisor vor all seinen Datenbanken einzusetzen, um eine Skalierung der Datenverarbeitung ohne Ausfallzeiten zu erm\xf6glichen. Discussion Service-Benutzer fordern die Hinzuf\xfcgung von vorbereiteten Anweisungen im Transaktions-Pooling-Modus und schlagen vor, Nimble_pool anstelle von Poolboy zu verwenden, w\xe4hrend sie die Unterst\xfctzung von Parallelit\xe4t und die Fehlertoleranz von Elixir loben. Ein Discussion Service-Benutzer berichtet \xfcber seine Arbeitserfahrungen mit Pgbouncer auf 4 vCPU-Maschinen und ein anderer \xfcber seinen Pool gemeinsamer Pgbouncer, die \xfcber Googles Cloud SQL Proxy zu verschiedenen PostgreSQL-Instanzen geleitet werden."]}),"\n",(0,t.jsx)(n.h2,{id:"neue-plagiatsvorw\xfcrfe-gegen-roy-lichtenstein",children:"Neue Plagiatsvorw\xfcrfe gegen Roy Lichtenstein"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://www.theguardian.com/artanddesign/2023/apr/09/new-allegations-of-plagiarism-against-roy-lichtenstein",children:"Original"}),'.\nGegen Roy Lichtenstein sind neue Plagiatsvorw\xfcrfe erhoben worden. In einem neuen Film wird behauptet, dass Hunderte seiner Werke auf andere K\xfcnstler zur\xfcckgehen. In dem Dokumentarfilm wird behauptet, dass sich der Begr\xfcnder der Pop-Art-Bewegung mehr als 30 Comic-K\xfcnstler "angeeignet" hat und mit dem Verkauf seiner Werke Millionen verdient hat, w\xe4hrend die kopierten Originalk\xfcnstler ein karges und sogar mittelloses Leben f\xfchrten. W\xe4hrend einige Lichtensteins Werk als "Aneignung" verteidigen, bezeichnen Kritiker es als Diebstahl, wobei neben "technisch und k\xfcnstlerisch" \xfcberlegenen Werken, die von Lichtenstein kopiert wurden, auch "regelrechte Plagiate" angef\xfchrt werden.']}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35501868",children:"Discussion Service"}),".\nNeue Plagiatsvorw\xfcrfe gegen Roy Lichtenstein l\xf6sen eine Diskussion \xfcber Ethik, Originalit\xe4t und Angemessenheit in der Kunstwelt aus. Discussion Service-Benutzer diskutieren dar\xfcber, ob Lichtensteins Arbeit transformativ ist oder unverhohlener Diebstahl mit minimalen \xc4nderungen. Es geht um Urheberrecht und geistiges Eigentum sowie um die Frage, welchen kulturellen Wert Comic-Kunst im Vergleich zu bildender Kunst hat. Die Debatte umfasst Meinungen \xfcber das Wesen der Kunst, das Schaffen und den Wert in der Kunstwelt. Die urspr\xfcnglichen Comiczeichner wurden laut dem Beitrag oft als schlecht bezahlte Ware betrachtet."]})]})}function o(e={}){const{wrapper:n}={...(0,s.R)(),...e.components};return n?(0,t.jsx)(n,{...e,children:(0,t.jsx)(h,{...e})}):h(e)}}}]);